"use strict";(globalThis.webpackChunkgrc||=[]).push([[46841],{95852(e){e.exports=JSON.parse('{"citeKey":"he2005incorporatingdata","slug":"he-2005-incorporating-data-6b4a","title":"Incorporating Data Movement into Grid Task Scheduling","authors":["X. He","X.-H. Sun"],"venue":"Lecture Notes in Computer Science, vol. 3795, pp. 394 - 405","type":"Conference","entryType":"inproceedings","date":"January, 2005","year":2005,"era":"iit","month":1,"doi":"10.1007/11590354_49","abstract":"Task Scheduling is a critical design issue of distributed computing. The emerging Grid computing infrastructure consists of heterogeneous resources in widely distributed autonomous domains and makes task scheduling even more challenging. Grid considers both static, unmovable hardware and moveable, replicable data as computing resources. While intensive research has been done on task scheduling on hardware computing resources and on data replication protocols, how to incorporate data movement into task scheduling seamlessly is unrevealed. We consider data movement as a dimension of task scheduling. A dynamic data structure, Data Distance Table (DDT), is proposed to provide real-time data distribution and communication information. Based on DDT, a data-conscious task scheduling heuristics is introduced to minimize the data access delay. A simulated Grid environment is set up to test the efficiency of the newly proposed algorithm. Experimental results show that for data intensive tasks, the dynamic data-conscious scheduling outperforms the conventional Min-Min significantly.","hasAbstract":true,"lede":"Task Scheduling is a critical design issue of distributed computing.","links":{"pdf":"https://grc.iit.edu/papers/2005/he-2005-incorporating-data-6b4a.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["ghs"],"memberAuthors":["sun-xian-he"]}')}}]);